-- P05 versioned synthetic seed. No existing proposal/grant/evidence is overwritten.
SELECT g.workspace_id,g.user_id,g.company_id,'schedule.read',g.scope_type,g.scope_id,g.site_id,g.valid_from,g.valid_to FROM ppo.permission_grants g
WHERE g.capability='service.work_order.read' AND g.valid_from<=clock_timestamp() AND (g.valid_to IS NULL OR g.valid_to>clock_timestamp()) ON CONFLICT DO NOTHING;
SELECT g.workspace_id,g.user_id,g.company_id,cap,g.scope_type,g.scope_id,g.site_id,g.valid_from,g.valid_to FROM ppo.permission_grants g CROSS JOIN (VALUES('schedule.manage'),('schedule.request'),('schedule.contact')) capabilities(cap)
WHERE g.capability='service.work_order.edit' AND g.valid_from<=clock_timestamp() AND (g.valid_to IS NULL OR g.valid_to>clock_timestamp()) ON CONFLICT DO NOTHING;

