WITH snapshot AS (SELECT jsonb_build_object('schema_version',1,'synthetic',true,'source','P05 SQL fixture','site',(SELECT to_jsonb(s) FROM ppo.sites s WHERE s.id=r.site_id),'scope',to_jsonb(r),'items',(SELECT jsonb_agg(to_jsonb(i)||jsonb_build_object('assets',(SELECT jsonb_agg(jsonb_build_object('asset_id',a.id,'asset_version',a.version,'identity_status',a.identity_status,'configuration_id',NULL,'display_number',a.display_number,'description',a.description)) FROM ppo.scope_assets sa JOIN ppo.assets a ON a.id=sa.asset_id WHERE sa.scope_item_id=i.id))) FROM ppo.scope_items i WHERE i.scope_revision_id=r.id),'readiness',(SELECT jsonb_agg(to_jsonb(x)) FROM ppo.readiness_assessments x WHERE x.scope_revision_id=r.id)) body FROM ppo.scope_revisions r WHERE r.id='aa000000-0000-4000-8000-000000000001')
UPDATE ppo.scope_revisions SET approved_by='30000000-0000-4000-8000-000000000001',approved_at=clock_timestamp(),approved_snapshot=snapshot.body,content_hash=encode(sha256(convert_to(snapshot.body::text,'UTF8')),'hex') FROM snapshot WHERE id='aa000000-0000-4000-8000-000000000001';
